// Build packaged Markdown libraries. Do not edit the generated bundle by hand.
import { build } from 'esbuild';
import { copyFile } from 'node:fs/promises';

await build({
  stdin: {
    contents: "export { marked } from 'marked'; export { default as DOMPurify } from 'dompurify';",
    resolveDir: process.cwd(),
  },
  bundle: true,
  format: 'iife',
  globalName: 'BibleGatewayAILibraries',
  outfile: 'extension/vendor/markdown.js',
  minify: true,
  banner: { js: '// Generated by npm run vendor:extension. Do not edit manually.' },
  legalComments: 'eof',
});

await copyFile('node_modules/marked/LICENSE', 'extension/vendor/marked.LICENSE');
await copyFile('node_modules/dompurify/LICENSE', 'extension/vendor/dompurify.LICENSE');
